CREATE TABLE shop_users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN ('CUSTOMER','ADMIN')),created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE products(id VARCHAR(255) PRIMARY KEY,name VARCHAR(255) NOT NULL,category VARCHAR(255) NOT NULL,description VARCHAR(255) NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>0),weight NUMERIC(8,3) NOT NULL CHECK(weight>0),image VARCHAR(255) NOT NULL,sizes VARCHAR(255) NOT NULL,colors VARCHAR(255) NOT NULL,featured BOOLEAN NOT NULL);
CREATE TABLE store_orders(id UUID PRIMARY KEY,reference VARCHAR(100) UNIQUE NOT NULL,customer_id BIGINT NOT NULL REFERENCES shop_users(id),receiver_name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,address VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,postal_code VARCHAR(20),subtotal NUMERIC(12,2) NOT NULL,shipping_charge NUMERIC(12,2),shipment_state VARCHAR(30) NOT NULL,tracking_number VARCHAR(100) UNIQUE,delivery_status VARCHAR(30),status_at TIMESTAMPTZ,submitted_at TIMESTAMPTZ,request_payload TEXT,last_error VARCHAR(400),created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_orders_customer ON store_orders(customer_id,created_at);
CREATE TABLE store_order_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id UUID NOT NULL REFERENCES store_orders(id),product_id VARCHAR(255) NOT NULL REFERENCES products(id),name VARCHAR(255) NOT NULL,image VARCHAR(255) NOT NULL,size VARCHAR(255) NOT NULL,color VARCHAR(255) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 10),unit_price NUMERIC(12,2) NOT NULL,weight NUMERIC(8,3) NOT NULL);
CREATE TABLE integration_settings(id BIGINT PRIMARY KEY CHECK(id=1),gateway_url VARCHAR(255) NOT NULL,api_key_cipher TEXT,secret_cipher TEXT,pickup_name VARCHAR(255) NOT NULL,pickup_phone VARCHAR(255) NOT NULL,pickup_address VARCHAR(255) NOT NULL,pickup_city VARCHAR(255) NOT NULL,pickup_postal VARCHAR(255) NOT NULL,failure_mode VARCHAR(255) NOT NULL,failures_remaining INTEGER NOT NULL DEFAULT 0);
CREATE TABLE webhook_events(event_id UUID PRIMARY KEY,payload_hash VARCHAR(64) NOT NULL,event_type VARCHAR(255) NOT NULL,tracking_number VARCHAR(100),merchant_reference VARCHAR(100),new_status VARCHAR(30),occurred_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,order_id UUID REFERENCES store_orders(id));
CREATE INDEX idx_events_tracking ON webhook_events(tracking_number);
CREATE INDEX idx_events_reference ON webhook_events(merchant_reference);
CREATE TABLE webhook_attempts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id UUID,received_at TIMESTAMPTZ NOT NULL,http_status INTEGER NOT NULL,outcome VARCHAR(40) NOT NULL);
